package rules

import (
	"strings"
	"testing"

	"github.com/fabriziosalmi/agssh/internal/manifest"
)

// TestSpecCoversRegistry pins the embedded standard text (spec.json, generated by
// standard/build_pdf.py) to the registry: every rule the runner enforces has its
// why / check / fix / tool text, the spec names no rule the runner lacks, and the
// version is the one the runner reports. The MCP server serves this text as the
// agssh://rules/{id} resources, so a gap here would be a rule a model cannot read.
func TestSpecCoversRegistry(t *testing.T) {
	s, err := StandardSpec()
	if err != nil {
		t.Fatalf("StandardSpec: %v", err)
	}
	if s.Version != StandardVersion {
		t.Errorf("spec.json version %q != StandardVersion %q (regenerate: cd standard && python build_pdf.py)", s.Version, StandardVersion)
	}

	inSpec := map[string]bool{}
	for _, f := range s.Families {
		for _, r := range f.Rules {
			if inSpec[r.ID] {
				t.Errorf("%s: duplicate id in spec.json", r.ID)
			}
			inSpec[r.ID] = true
			if !strings.HasPrefix(r.ID, f.Prefix+"-") {
				t.Errorf("%s: filed under family %s", r.ID, f.Prefix)
			}
		}
	}
	for _, r := range All() {
		sr, fam, ok := SpecFor(r.ID)
		if !ok {
			t.Errorf("%s: enforced by the registry but has no text in spec.json", r.ID)
			continue
		}
		if fam.Prefix != r.Family {
			t.Errorf("%s: family registry=%s spec=%s", r.ID, r.Family, fam.Prefix)
		}
		for name, v := range map[string]string{"why": sr.Why, "check": sr.Check, "fix": sr.Fix, "tool": sr.Tool, "applies": sr.Applies} {
			if strings.TrimSpace(v) == "" {
				t.Errorf("%s: empty %s text", r.ID, name)
			}
		}
		delete(inSpec, r.ID)
	}
	for id := range inSpec {
		t.Errorf("%s: in spec.json but not in the registry", id)
	}
	if len(s.Profiles) != 3 || len(s.Levels) != 3 {
		t.Errorf("profile/level tables: got %d profiles, %d levels; want 3 and 3", len(s.Profiles), len(s.Levels))
	}
	for i, p := range s.Profiles {
		if want := manifest.Profile(i + 1).String(); p.Name != want {
			t.Errorf("profile row %d is %q, want %q", i, p.Name, want)
		}
	}
	for i, l := range s.Levels {
		if want := manifest.Level(i).String(); l.Name != want {
			t.Errorf("level row %d is %q, want %q", i, l.Name, want)
		}
	}
}

func TestLookupIsCaseInsensitive(t *testing.T) {
	if r, ok := Lookup("ag-hdr-01A"); !ok || r.ID != "AG-HDR-01a" {
		t.Errorf("Lookup(ag-hdr-01A) = %q, %v", r.ID, ok)
	}
	if _, ok := Lookup("AG-NOPE-99"); ok {
		t.Errorf("Lookup found a rule that does not exist")
	}
}
